AtomicLong counter = new AtomicLong();

Runnable work = () -> {
	for (int i = 0; i < 1_000_000; i++) {
		counter.incrementAndGet();
	}
};

// 8 threads run `work`; the main thread joins all of them
System.out.println(counter.get());

