var n int64
var wg sync.WaitGroup

for i := 0; i < 8; i++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for j := 0; j < 1000; j++ {
			n++
		}
	}()
}

wg.Wait()
fmt.Println(n)

